import java.util.*;

public class GameStages {
    private static List<List<Node>> adjList;
    private static int[] dist;
    private static final int INF = Integer.MAX_VALUE;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        adjList = new ArrayList<>(n + 1);
        for (int i = 0; i <= n; i++) {
            adjList.add(new ArrayList<>());
        }
        dist = new int[n + 1];
        Arrays.fill(dist, INF);

        for (int i = 1; i < n; i++) {
            int a = in.nextInt();
            int b = in.nextInt();
            int x = in.nextInt();
            adjList.get(i).add(new Node(i + 1, a));
            adjList.get(i).add(new Node(x, b));
        }

        System.out.println(dijkstra(1, n));
        in.close();
    }

    private static int dijkstra(int start, int end) {
        PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingInt(node -> node.cost));
        pq.add(new Node(start, 0));
        dist[start] = 0;

        while (!pq.isEmpty()) {
            Node current = pq.poll();
            int currentNode = current.node;
            int currentCost = current.cost;

            if (currentCost > dist[currentNode]) {
                continue;
            }

            for (Node neighbor : adjList.get(currentNode)) {
                int newDist = dist[currentNode] + neighbor.cost;
                if (newDist < dist[neighbor.node]) {
                    dist[neighbor.node] = newDist;
                    pq.add(new Node(neighbor.node, newDist));
                }
            }
        }
        return dist[end];
    }

    private static class Node {
        int node;
        int cost;

        Node(int node, int cost) {
            this.node = node;
            this.cost = cost;
        }
    }
}
